data.transform:
(
	$request := $state.context.REQUEST.DATA;
	$ps := $state.context.LOCAL.DATA;
	$formData := $request.formData;
	$targetProduct := $formData.product.id;
	$strategyType := $ps.manufactured
		? "Manufactured"
		: $ps.purchased
			? "Purchased"
			: $ps.nonInventory
				? "Non-Inventory"
				: $ps.leading
					? "Leading"
					: $ps.phantom
						? "Phantom"
						: $ps.byProduct
							? "By-Product"
							: "Undefined";
	$psId := $formData.product.number & "." & $formData.product.version
		& "_"
		& $formData.name
		& "_"
		& $formData.revision
		& "_"
		& $strategyType;
	/* Setup product strategy */
	$psPayload := $merge([
		$omit($ps, ["productStrategyProcesses", "assemblyBoms"]),
		{
			"id": $psId,
			"productId": $targetProduct,
			"validated": false,
			/* Additional Data from the request -> {name}-{strategyTypeId}-{revision} */
			"code": $psId,
			"name": $state.context.REQUEST.DATA.name,
			"revision": $state.context.REQUEST.DATA.revision
		}
	])
		.{ "create": $ };
	$payloads := $ps
		.productStrategyProcesses
		.edges
		.node
		.(
			$currentProcess := $;
			$pid := $cuid();
			{
				/* Setup product strategy <- strategy processes */
				"pspPayload": $merge([
					$omit(
						$currentProcess,
						["assemblyBoms", "alternateWorkunits", "processSteps"]
					),
					{ "id": $pid, "productStrategyId": $psId }
				])
					.{ "create": $ },
				"bomPayload": $filter(
					$map(
						$currentProcess.assemblyBoms.edges,
						function($edge) {
							$exists($edge.node) and $count($keys($edge.node)) > 0
								and $formData.copyBom
								? {
									"create": $merge([
										$edge.node,
										{ "assemblyProductStrategyProcessId": $pid }
									])
								}
								: ()
						}
					),
					function($item) { $exists($item.create) }
				),
				"altWcPayload": $formData.copyAltWc
					? $map(
						$currentProcess.alternateWorkunits.edges,
						function($edge) {
							$exists($edge.node) and $count($keys($edge.node)) > 0
								? {
									"create": $merge([
										$edge.node,
										{ "productStrategyProcessId": $pid }
									])
								}
								: []
						}
					)
					: [],
				"steps": $formData.copySteps
					? $map(
						$currentProcess.processSteps.edges,
						function($edge) {
							$exists($edge.node) and $count($keys($edge.node)) > 0
								? {
									"create": $merge([
										$edge.node,
										{ "productStrategyProcessId": $pid }
									])
								}
								: []
						}
					)
					: []
			}
		);
	{
		"psPayload": [$psPayload],
		"pspPayload": [$payloads.pspPayload],
		"bomPayload": [$payloads.bomPayload],
		"altWcPayload": [$payloads.altWcPayload],
		"stepPayload": [$payloads.steps]
	}
)

