data.query:
query getProductStrategy(
  $dataWhere:ProductStrategyWhereInput, 
){
  getData:productStrategy(where:$dataWhere)
  {
    edges{node {id code weight active primary validated customData integrationData 
                productId productStrategyStageId strategyTypeId consumptionUnitId
                inventoryUnitId purchaseUnitId saleUnitId unitTypeId weightUnitId

          strategyProcesses {
          edges{node{id code standardPositions standardWorkunits cycleTime 
                      distributionPercentage idealRate leadTime minimumProductionRunTime
                      percentToStart productionOffalAllowed productionOperators setupRate
                      setupOffalAllowed setupOperators setupRate standardRate timeToStart
                      transitTimeAfter transitTimeBefore unitPerCycle unitWeight active 
                      allowMixedLots autoTriggerDependency defaultDistribution final
                      generatePurchaseOrder rawMaterial requireReceipt transferSerial 
                      useSupplierLabel useWorkunitRates wip description externalId
                      order customData integrationData processId productionTypeId 
                      controlPanelId documentDesignId lotControlId putAwayLocationId
                      schedulingGroupId weightUnitId workunitId
            					standardWorkunits
                      supplierReturnLines{edges{node{id}}} 
                      qualityReports{edges{node{id}}} 
                      qualitySubjectLists{edges{node{id}}}
    									workOrderProcesses{edges{node{id}}}
            					alternateWorkunits{edges{node{id}}}
            					packagingConfigurations{edges{node{id}}}

                      assemblyBoms{
                      edges{node{order fixedLaborUsage fixedMachineUsage fixedMaterialUsage
                              laborUsage machineUsage maximumUsage minimumUsage rate 
                              standardPackQuantity standardUsage unitPerCycle active 
                              buildWorkOrder defaultPackaging useOnWorkOrder externalId reference
                              customData integrationData assemblyProductStrategyProcessId bomTypeId 
                              componentPackagingMaterialId componentProductId componentProductStrategyId
                              componentProductStrategyProcessId consumptionModeId
                        }}
                      }

          }} 
          } 
    }}
  }
}

